// CLAUDE SUMMARY APPROVAL GATE (DEC-112/122, WF12-LLMGATE-001) — a DECISION, not a throw. In agent chains a
// Code-node throw kills WF12->WF20->WF18 and the user gets nothing; the correct degradation is the deterministic
// report ($0). The gate stays fail-closed for the LLM: any unmet condition -> llm_gate_allowed=false and the
// following IF routes straight to the report append. executeWorkflow passes booleans as STRINGS ('true') — accept
// both. Claude remains the interpretation layer ON TOP of the deterministic fact core: no invented facts/contacts.
function str(v){return v==null?'':String(v).trim();}
function boolish(v){return v===true||str(v).toLowerCase()==='true';}
const cfg=$('Set Report Config').first().json;
const _rep=(($input.all()[0]||{json:{}}).json)||{};
let allowed=true, reason='ok';
if(!boolish(cfg.enable_llm_summary)){ allowed=false; reason='llm_summary_disabled'; }
else if(!(Number(_rep.rows_after_filters)>0)||_rep.report_eligible===false){ allowed=false; reason='no_eligible_facts'; }
else if(str(_rep.llm_summary_status)==='summarized'||_rep.already_summarized===true){ allowed=false; reason='already_summarized_idempotency'; }
else if(str(cfg.llm_approval_token)!=='I_APPROVE_CLAUDE_REPORT_SUMMARY'){ allowed=false; reason='approval_token_missing'; }
return $input.all().map(it=>({json:Object.assign({},it.json,{llm_gate_allowed:allowed,llm_gate_reason:reason})}));

